mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.yz = rot(0.8) * p.yz;
  p.xz = rot(time * 0.3) * p.xz;
  float r = length(p.xz);
  float a = atan(p.z, p.x);
  float petals = sin(a * 8.0) * 0.28 * (1.0 + 0.3 * sin(time * 2.0));
  float dome = length(vec3(r - 1.05, p.y + r * 0.32 - petals, 0.0)) - 0.09;
  float core = length(p) - 0.32;
  return min(dome, core);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.5, -3.2);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 7.0) break;
    t += d * 0.75;
  }
  vec3 col = glow * vec3(1.1, 0.2, 0.7) * (0.8 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
